using System;using System.Collections.Generic;public class PriorityStack<T>{private class StackItem{public T Value;public int Priority;public StackItem(T value,int priority){Value=value;Priority=priority;}}private List<StackItem> items=new List<StackItem>();public void Push(T value,int priority){items.Add(new StackItem(value,priority));}public T Pop(){if(IsEmpty())throw new InvalidOperationException("The stack is empty.");int maxPriority=int.MinValue;foreach(var item in items){if(item.Priority>maxPriority)maxPriority=item.Priority;}for(int i=0;i<items.Count;i++){if(items[i].Priority==maxPriority){T value=items[i].Value;items.RemoveAt(i);return value;}}throw new InvalidOperationException("No item found with the highest priority.");}public bool IsEmpty(){return items.Count==0;}}